class TestSet(ATTestSet.TestSet):

    FEATURES = ['ALL']

    def _ck_bind_link(self, setup, dut, misc, role):
        """Resolve `[misc] ck_link_<role>` on THIS bench, bind it, and assert its media.

        Fixed frame — do not edit or delete. Three failures it converts from silent to loud:
          1. an undeclared role: the bench has not agreed to host this test;
          2. `init_portlink()` returning (None, None) for a link the bench does not have —
             a None port later renders as `interface None`, so the run fails looking like a
             SCRIPT defect;
          3. the bound port being the wrong MEDIA. That one cannot be caught offline: media
             belongs to the pluggable, and the CLI accepts `polarity`/`speed 100` on fibre
             where they are meaningless, so the run would report a PRODUCT failure that is
             really a cabling error.
        Raising aborts the suite on purpose: "this bench cannot host this test" is not a
        test result. See ask-ck/pytest-create/TOPOLOGY-PROFILES.md.
        """
        import ck_media
        ref = misc.get('ck_link_' + role)
        if not ref:
            raise RuntimeError(
                "BENCH PROBLEM, not a product defect: this .setup declares no "
                "ck_link_%s, so the %s link this test needs is not available here. "
                "See TOPOLOGY-PROFILES.md." % (role, role))
        dev_a, dev_b, _named_port = ck_media.parse_link_ref(ref)
        dut_key = misc.get('ck_role_dut', 'swi_a')
        far_key = dev_b if dev_a == dut_key else dev_a
        far = setup.init_swi(far_key)
        (near_port, far_port) = setup.init_portlink(dut, far, type1='port', type2='port')
        if near_port is None or far_port is None:
            raise RuntimeError(
                "BENCH PROBLEM, not a product defect: ck_link_%s = %r but no unused "
                "matching [portlink] exists between %s and %s." % (role, ref, dut_key, far_key))
        status = dut.cmd('show interface %s status' % near_port.name)
        ok, why = ck_media.assert_role_media(status, near_port.name, role)
        if not ok:
            raise RuntimeError(why)
        self.log('topology: role %r -> %s %s <-> %s %s (%s)' % (
            role, dut_key, near_port.name, far_key, far_port.name, why))
        return near_port, far_port, far

    def init(self, setup):
        # Topology is resolved from the .setup [misc] ROLE CONTRACT at run time, so this
        # script names no device and no port: it binds correctly on any bench that declares
        # the roles it needs, and fails loudly on one that does not. The role names come
        # from TOPOLOGY-PROFILES.md; the bench says what they mean HERE.
        tb = setup.init_tb()
        misc = setup.get_all_misc()
        dutA = setup.init_swi(misc.get('ck_role_dut', 'swi_a'))
        self.tb = tb
        self.dutA = dutA
        # Bind the ONE link this case needs from the bench's role contract, assert its media,
        # and take the PARTNER from that link's far end — no second lookup. Deterministic on
        # purpose: this used to be a FILL slot, and the model declared links the test never
        # used (T33235 bound 4 devices and 2 links while referencing 1 of each, so the script
        # demanded cabling for no reason). One link => exactly one partner.
        (dutA.portA, self.ck_far_port, dut) = self._ck_bind_link(
            setup, dutA, misc, 'copper')
        self.dut = dut
        # NOT BOUND: swiDst.
        # A test binds the DUT plus ONE partner (the far end of its one link). These names
        # were only ever inferred from the vocabulary of the selected fragments, which is not
        # evidence the test needs them — and every unused binding becomes a topology demand
        # a bench has to satisfy for nothing. Needing a second partner means declaring a
        # second link role in TOPOLOGY-PROFILES.md, not guessing a device here.

    def configure(self):
        # One-time SUITE setup, runs ONCE before all test cases. Config only — no pass/fail.
        # Adapted from ART 1348_security/test-1348.1001.py (RADIUS + dot1x CLI) and
        # ART 1341_limits/test-1341.6001.py (VLAN/RADIUS-assigned-VLAN mechanics).
        from framework.ATLibrary import ATRadius
        dutA = self.dutA
        tb = self.tb
        port = dutA.portA

        self.dataVlan = 100
        self.guestVlan = 200
        self.supUser = 'user1'
        self.supPass = 'user1'
        radServer = tb.ethA.get_ipv4_addr(1)
        self.radServer = radServer

        # RADIUS server on the testbox, returning the data VLAN for the single supplicant.
        radiusManager = ATRadius.RadiusManager(
            logFilePath=getattr(self, 'logFilePath', None), testEntity=self,
            verbose=getattr(self, 'debug', False))
        radiusManager.clear_users()
        user = ATRadius.RadiusUser(self.supUser, self.supPass)
        user.add_attribute('Egress-VLANID', 838860800 + self.dataVlan, plusEqual=True)
        radiusManager.add_users(user)
        try:
            started = radiusManager.start(testCase=self)
        except TypeError:
            started = radiusManager.start()
        if not started:
            raise RuntimeError('A problem occurred starting the radius server for 802.1X setup')
        self.radiusManager = radiusManager

        # Data VLAN(s) that RADIUS may assign, plus the Guest VLAN referenced by the test.
        dutA.mode(')#')
        dutA.cmd('vlan database')
        dutA.cmd('vlan {},{}'.format(self.dataVlan, self.guestVlan))

        # RADIUS server + dot1x enabled system-wide.
        dutA.mode(')#')
        dutA.cmd('radius-server host {} key secret'.format(radServer))
        dutA.cmd('aaa authentication dot1x default group radius')

        # Interface: single-host 802.1X with a Guest VLAN.
        dutA.cmd('interface {}'.format(port.name))
        dutA.cmd('dot1x port-control auto')
        dutA.cmd('auth host-mode single-host')
        dutA.cmd('auth guest-vlan {}'.format(self.guestVlan))
        dutA.mode('#')

    def tear_down(self):
        # One-time SUITE cleanup, runs ONCE after all cases. No pass/fail.
        dutA = self.dutA
        port = dutA.portA
        if getattr(self, 'radiusManager', None):
            self.radiusManager.stop()
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(port.name))
        dutA.cmd('no auth guest-vlan')
        dutA.cmd('no auth host-mode')
        dutA.cmd('no dot1x port-control')
        dutA.mode(')#')
        dutA.cmd('no radius-server host {} key secret'.format(getattr(self, 'radServer', '')))
        dutA.cmd('no aaa authentication dot1x default')
        dutA.cmd('vlan database')
        dutA.cmd('no vlan {},{}'.format(
            getattr(self, 'dataVlan', 100), getattr(self, 'guestVlan', 200)))
        dutA.mode('#')


class TestCase_1(ATTestCase.TestCase):
    testCaseDesc = 'With the supplicant connected but before any 802.1X authentication is attempted, use Scapy/tcpdump on the partner to send a non-EAPOL data frame (e.g. an ARP or IP packet) from the supplicant into the test port and capture on the far side of the assigned VLAN.'
    testCaseRef = 'AWPTCM-T33351'
    testCaseMethod = "With the supplicant connected but before any 802.1X authentication is attempted, use Scapy/tcpdump on the partner to send a non-EAPOL data frame (e.g. an ARP or IP packet) from the supplicant into the test port and capture on the far side of the assigned VLAN. | verify: The non-EAPOL frame is NOT forwarded (no capture on the egress side); 'show dot1x' for the test port reports 'portStatus: Unauthorized'. Only EAPOL frames are accepted at this stage."

    def main(self):
        # legacy tools/auth_simulator/dot1x_simulator.py lines 299-317
        self.log('STEP 1: With the supplicant connected but before any 802.1X authentication is attempted, use Scapy/tcpdump on the partner to send a non-EAPOL data frame (e.g. an ARP or IP packet) from the supplicant into the test port and capture on the far side of the assigned VLAN.')
        import library_802_1x_single_host as lib
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        port = dutA.portA
        rx = getattr(tb, 'ethB', None)
        if rx is None:
            self.failed('BENCH PROBLEM, not a product defect: no second testbox interface '
                        '(ethB) is available to capture the egress side of the assigned VLAN.')
            return
        frame = lib.make_arp_frame(tb.ethA.macAddr, '192.0.2.10', '192.0.2.1')
        pkts = lib.send_and_capture(tb.ethA.name, rx.name, frame, bpf='arp')
        captured = len(pkts)
        dutA.mode('#')
        dot1x = dutA.cmd('show dot1x interface {}'.format(port.name))
        self.log(dot1x)
        unauth = 'Unauthorized' in dot1x
        output = 'egress ARP frames captured={}; show dot1x Unauthorized present={}'.format(
            captured, unauth)
        self.log('OBSERVED: {}'.format(output))
        if captured == 0 and unauth:
            self.passed("Pre-auth non-EAPOL frame was NOT forwarded (0 captured on egress) and "
                        "show dot1x reports Unauthorized on {} — only EAPOL is accepted".format(port.name))
        else:
            self.failed("Expected no forwarding and Unauthorized, but captured={} egress frame(s) "
                        "and Unauthorized present={} on {}".format(captured, unauth, port.name))

    def tear_down(self):
        # Per-case cleanup so the next case starts clean. No pass/fail.
        pass


