    testCaseRef = 'AWPTCM-T33351'
    testCaseMethod = "On the single-host test port, attempt the unsupported dynamic VLAN option: 'auth dynamic-vlan-creation type multi'. | verify: The CLI rejects the command with an error (the 'type' keyword is not accepted in single-host / on platforms that only support 'auth dynamic-vlan-creation [rule {deny|permit}]'); the running-config for the port does not contain the rejected option."

    def main(self):
        # ART 1341_limits/test-1341.6001.py lines 274-457
        self.log("STEP 6: On the single-host test port, attempt the unsupported dynamic VLAN option: 'auth dynamic-vlan-creation type multi'.")
        dutA = self.testSet.dutA
        port = dutA.portA
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(port.name))
        out = dutA.cmd('auth dynamic-vlan-creation type multi')
        dutA.mode('#')
        run = dutA.cmd('show running-config interface {}'.format(port.name))
        self.log(out)
        self.log(run)
        rejected = ('%' in out) or ('nrecognized' in out) or ('nvalid' in out) or ('rror' in out)
        not_present = 'type multi' not in run
        output = 'command rejected={}, "type multi" absent from run-config={}'.format(
            rejected, not_present)
