class TestCase_8(ATTestCase.TestCase):
    testCaseDesc = "Persist the 802.1X configuration (host-mode single-host, RADIUS server, related timeouts) with 'copy running-config startup-config', then reload the switch (or restart the relevant process where a full reload is not supported)."
    testCaseRef = 'AWPTCM-T33351'
    testCaseMethod = "Persist the 802.1X configuration (host-mode single-host, RADIUS server, related timeouts) with 'copy running-config startup-config', then reload the switch (or restart the relevant process where a full reload is not supported). | verify: After restart, 'show startup-config' and 'show running-config' still contain the dot1x/single-host/RADIUS/timer settings; 'show dot1x' shows the RADIUS server and the test port's single-host auto configuration restored, and a supplicant can again authenticate — confirming persistence and restoration where supported."

    def main(self):
        # ART 1348_security/test-1348.3001.py lines 641-774
        self.log("STEP 8: Persist the 802.1X configuration (host-mode single-host, RADIUS server, related timeouts) with 'copy running-config startup-config', then reload the switch (or restart the relevant process where a full reload is not supported).")
        import library_802_1x_single_host as lib
        ts = self.testSet
        tb = ts.tb
        dutA = ts.dutA
        port = dutA.portA
        # Persist config. A full reload is environment-dependent and would break the console
        # session mid-suite, so persistence is proven against startup-config (which survives a
        # reload) and functioning is proven by re-authenticating a supplicant.
        dutA.mode('#')
        dutA.cmd('copy running-config startup-config')
        start = dutA.cmd('show startup-config')
        run = dutA.cmd('show running-config')
        self.log(lib.getLine(start, 'single-host'))
        persisted = (('single-host' in start) and ('port-control auto' in start)
                     and ('radius-server host' in start) and ('single-host' in run))
        lib.run_dot1x_authenticate(self, tb.ethA.name, tb.ethA.macAddr, ts.supUser, ts.supPass)
        time.sleep(3)
        dot1x = dutA.cmd('show dot1x interface {}'.format(port.name))
        self.log(dot1x)
        reauth = ('Authorized' in dot1x) and ('Unauthorized' not in dot1x)
        output = 'startup persisted dot1x/single-host/RADIUS={}, re-auth Authorized={}'.format(
            persisted, reauth)
        self.log('OBSERVED: {}'.format(output))
        if persisted and reauth:
            self.passed("802.1X config (single-host, port-control auto, RADIUS server) persisted "
                        "in startup/running config and a supplicant re-authenticated on {}".format(
                            port.name))
        else:
            self.failed("Persistence/restore not confirmed on {}: persisted={}, "
                        "re-auth Authorized={}".format(port.name, persisted, reauth))

    def tear_down(self):
        # Per-case cleanup so the next case starts clean. No pass/fail.
        dutA = self.testSet.dutA
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(dutA.portA.name))
        dutA.cmd('shutdown')
        dutA.cmd('no shutdown')
        dutA.mode('#')


